{
  "summary": "Three medication safety findings were identified regarding your current prescriptions and lab results. Please review these with your doctor or pharmacist.",
  "explanations": [
    {
      "finding_id": "DEMO-INT-002",
      "plain_language": "Taking Tritace and Aldactone together can increase blood potassium levels. Having chronic kidney disease further increases this risk because reduced kidney function lowers potassium clearance. Please discuss this combination with your doctor or a pharmacist. Do not stop or change either medicine on your own."
    },
    {
      "finding_id": "DEMO-LAB-001:glucophage",
      "plain_language": "Glucophage is generally not used when kidney function is below 30 due to the risk of lactic acidosis. Your recent test shows kidney function at 24. Contact your prescribing doctor or a pharmacist promptly to discuss this. Do not stop taking your medicine on your own."
    },
    {
      "finding_id": "DEMO-LAB-002:aldactone",
      "plain_language": "Aldactone can raise blood potassium, and your recent lab result shows potassium above the usual limit. Contact your prescribing doctor or a pharmacist promptly to review this finding. Do not stop your medicine on your own."
    }
  ]
}
